create schema auth; create schema private; create role anon; create role authenticated;
create function auth.uid() returns uuid language sql as $$select case when current_setting('test.deny',true)='yes' then null else '00000000-0000-0000-0000-000000000001'::uuid end$$;
create function private.rrhh_partidas_permiso(text,integer,text) returns boolean language sql as $$select auth.uid() is not null$$;
create function private.obraxis_permission(text,text) returns boolean language sql as $$select auth.uid() is not null$$;
create table public.avances_produccion_partidas(id integer,created_at timestamp with time zone,obra_nombre text,supervisor text,frente text,partida text,unidad text,cantidad numeric,observaciones text,obra_id integer,empresa text,partida_id integer,cuadrilla_id bigint,cuadrilla_nombre text,cuadrilla_miembros jsonb,horas_cuadrilla numeric,specialty_session_id uuid);
create table public.maestro_personal(id integer,obra_nombre text,nombre text,rut text,cargo text,inicio text,termino text,colacion numeric,movilizacion numeric,created_at timestamp with time zone,empresa text,fono text,email text,centro_trabajo text,area text,sueldo_base numeric,tipo_contrato text,fecha_inicio_contrato date,fecha_vencimiento_contrato date,banco text,tipo_cuenta text,numero_cuenta text,afp text,prevision_salud text,centro_trabajo_id bigint,centro_gestion_id integer,fecha_asig date,gratificacion text,centro_gestion_defecto_id integer,horas_semanales numeric,causal_termino_contrato text,otras_asignaciones jsonb,estado text);
create table public.obra_cuadrillas(id bigint generated by default as identity primary key,empresa text,obra_id integer,obra_nombre text,nombre text,lider text,especialidad text,miembros jsonb,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.obra_liquidaciones(id bigint,empresa text,obra_id integer,obra_nombre text,trabajador text,periodo text,num_folio text,monto_real numeric,partida text,created_at timestamp with time zone,nomina_id bigint,nomina_item_id bigint,trabajador_id integer,monto_liquidacion_total numeric,dias_imputados numeric,porcentaje_imputacion numeric,criterio_imputacion text);
create table public.obras(id integer primary key,nombre text,tipo text,link text,area text,administrador text,oficina_tecnica text,prevencionista text,created_at timestamp with time zone,imagen_base64 text,empresa text,latitud numeric,longitud numeric,radio_cobertura_m numeric,cliente text,cliente_email text,cliente_telefono text,ubicacion text,admin_contrato text,estado text,fecha_termino_real date,motivo_cierre text,centro_gestion_id integer,centro_trabajo_id bigint,asistencia_token text,fecha_inicio_real date,fecha_termino_estimada date,presupuesto_costo_control numeric,jornada_ordinaria_horas numeric,jornada_semanal jsonb,margen_presupuestado_pct numeric,jornadas_historial jsonb);
create table public.partidas_obra(id integer,obra_nombre text,partida text,unidad text,rendimiento_meta numeric,cantidad_presupuestada numeric,costo_por_dia numeric,created_at timestamp with time zone,codigo text,fecha_inicio date,fecha_termino date,obra_id integer,empresa text,orden integer,es_titulo boolean,predecesora text,tipo_relacion text,desfase_dias integer,presupuesto_item_id integer,tipo_item text,nivel integer,parent_codigo text,moneda_pu text,pu_original numeric,cambio_pu_clp numeric);
create table public.rrhh_costos_centros_aprobados(nomina_id bigint,nomina_item_id bigint,empresa text,centro_gestion_id integer,dias numeric,monto numeric,distribuido_por uuid,distribuido_en timestamp with time zone,dias_detalle jsonb);
create table public.rrhh_imputaciones_diarias(id bigint,empresa text,trabajador_id integer,fecha date,origen text,evidencia jsonb,centro_propuesto_id integer,centro_aprobado_id integer,estado text,aprobado_por uuid,aprobado_en timestamp with time zone,comentario text,historial jsonb,costo_detalle jsonb,costo_evidencia jsonb,costo_total numeric,haber_imponible numeric,haber_no_imponible numeric,horas_extra_aprobadas numeric,asignacion_automatica boolean);
create table public.rrhh_nomina_items(id bigint,nomina_id bigint,trabajador_id integer,trabajador_rut text,trabajador_nombre text,obra_nombre text,cargo text,novedades jsonb,calculo jsonb,sueldo_liquido numeric,created_at timestamp with time zone,centro_gestion_id integer);
create table public.rrhh_nominas_mensuales(id bigint,empresa text,periodo text,estado text,parametros jsonb,total_haberes numeric,total_descuentos numeric,total_liquido numeric,generado_por text,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.rrhh_partidas_decisiones(empresa text,obra_id integer,trabajador_id integer,fecha date,distribucion jsonb,motivo text,version integer,actualizado_por uuid,actualizado_en timestamp with time zone,historial jsonb);
